   492	/**
   493	 * Expand variables in string
   494	 * @param parser
   495	 * @param dst
   496	 * @param src
   497	 * @param in_len
   498	 * @return
   499	 */
   500	static ssize_t
   501	ucl_expand_variable (struct ucl_parser *parser, unsigned char **dst,
   502	                const char *src, size_t in_len)
   503	{
   504	        const char *p, *end = src + in_len;
   505	        unsigned char *d;
   506	        size_t out_len = 0;
   507	        bool vars_found = false;
   508	
   509	        if (parser->flags & UCL_PARSER_DISABLE_MACRO) {
   510	                *dst = NULL;
   511	                return in_len;
   512	        }
   513	
   514	        p = src;
   515	        while (p != end) {
   516	                if (*p == '$') {
   517	                        p = ucl_check_variable (parser, p + 1, end - p - 1, &out_len, &vars_found);
   518	                }
   519	                else {
   520	                        p ++;
   521	                        out_len ++;
   522	                }
   523	        }
   524	
   525	        if (!vars_found) {
   526	                /* Trivial case */
   527	                *dst = NULL;
   528	                return in_len;
   529	        }
   530	
   531	        *dst = UCL_ALLOC (out_len + 1);
   532	        if (*dst == NULL) {
   533	                return in_len;
   534	        }
   535	
   536	        d = *dst;
   537	        p = src;
   538	        while (p != end) {
   539	                if (*p == '$') {
   540	                        p = ucl_expand_single_variable (parser, p, end - p, &d);
   541	                }
   542	                else {
   543	                        *d++ = *p++;
   544	                }
   545	        }
   546	
   547	        *d = '\0';
   548	
   549	        return out_len;
   550	}
