   625	/**
   626	 * Create and append an object at the specified level
   627	 * @param parser
   628	 * @param is_array
   629	 * @param level
   630	 * @return
   631	 */
   632	static inline ucl_object_t *
   633	ucl_parser_add_container (ucl_object_t *obj, struct ucl_parser *parser,
   634	                bool is_array, uint32_t level, bool has_obrace)
   635	{
   636	        struct ucl_stack *st;
   637	        ucl_object_t *nobj;
   638	
   639	        if (obj == NULL) {
   640	                nobj = ucl_object_new_full (is_array ? UCL_ARRAY : UCL_OBJECT, parser->chunks->priority);
   641	                if (nobj == NULL) {
   642	                        goto enomem0;
   643	                }
   644	        } else {
   645	                if (obj->type == (is_array ? UCL_OBJECT : UCL_ARRAY)) {
   646	                        /* Bad combination for merge: array and object */
   647	                        ucl_set_err (parser, UCL_EMERGE,
   648	                                        "cannot merge an object with an array",
   649	                                        &parser->err);
   650	
   651	                        return NULL;
   652	                }
   653	                nobj = obj;
   654	                nobj->type = is_array ? UCL_ARRAY : UCL_OBJECT;
   655	        }
   656	
   657	        if (!is_array) {
   658	                if (nobj->value.ov == NULL) {
   659	                        nobj->value.ov = ucl_hash_create (parser->flags & UCL_PARSER_KEY_LOWERCASE);
   660	                        if (nobj->value.ov == NULL) {
   661	                                goto enomem1;
   662	                        }
   663	                }
   664	                parser->state = UCL_STATE_KEY;
   665	        } else {
   666	                parser->state = UCL_STATE_VALUE;
   667	        }
   668	
